CASCOS={'pichon':'the white flight helmet, slightly too big for him,','tero':'the white flight helmet'}
def aplicar(PJ):
    for d in PJ:
        k=d['key']
        if k in OVR:
            d['packs']=[(f'{i+2:02d}',nom,(CAB(CASCOS[k]) if bg=='CAB' else bg),c) for i,(n,nom,bg,c) in enumerate(OVR[k])]
